async ({ session: { outline }, pr: { inspect }, workspace: { read, glob } }) => {
  const o = await outline({ previewChars: 120 });
  const states: Record<string, number> = {};
  for (const e of o.entries) states[e.state] = (states[e.state] ?? 0) + 1;
  const elidedIds = o.entries.filter((e: any) => e.state === "elided").map((e: any) => e.id);
  const pr = await inspect({ number: 397 });
  const skill = await read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" });
  const refs = await glob([".pi/skills/pit-delivery/**"]);
  return { tokens: o.estimatedTokens ?? o.tokens, count: o.entries.length, states, elidedIds, pr, skill: skill.content, refs };
}
